import 'dart:math';

/// Pure Dart Lights Out puzzle. Each move toggles the pressed cell and
/// its orthogonal neighbors. Starting boards are always generated by legal moves.
class LightGridSession {
  LightGridSession({required int seed, int scrambleCount = 4}) {
    final random = Random(seed);
    scrambleMoves = List<int>.generate(scrambleCount, (_) => random.nextInt(9));
    for (final index in scrambleMoves) {
      _toggle(index);
    }
    if (litCount == 0) {
      // A single legal move always creates a nontrivial solvable board.
      scrambleMoves.add(4);
      _toggle(4);
    }
  }

  final List<bool> lights = List<bool>.filled(9, false);
  late final List<int> scrambleMoves;
  int moves = 0;

  int get litCount => lights.where((value) => value).length;
  bool get finished => litCount == 0 && moves > 0;

  void _toggle(int index) {
    final row = index ~/ 3;
    final col = index % 3;
    for (var i = 0; i < 9; i++) {
      final distance = (i ~/ 3 - row).abs() + (i % 3 - col).abs();
      if (distance <= 1) lights[i] = !lights[i];
    }
  }

  bool tap(int index) {
    if (index < 0 || index >= 9 || finished) return false;
    _toggle(index);
    moves++;
    return true;
  }
}
